<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · Edvora ERP</title><style>*{box-sizing:border-box}body{margin:0;font:14px Arial;background:#f4f5fa;color:#172038}.page{min-height:100vh;display:grid;grid-template-columns:1.2fr 1fr}.hero{background:linear-gradient(145deg,#16152e,#342b77);color:#fff;padding:9vw 8vw;position:relative;overflow:hidden}.hero:after{content:'';position:absolute;width:420px;height:420px;border-radius:50%;background:#6d59e9;filter:blur(1px);opacity:.18;right:-150px;bottom:-170px}.brand{font-weight:800;font-size:21px}.hero h1{font-size:46px;line-height:1.12;margin:15vh 0 18px;max-width:560px}.hero p{color:#c5c1df;line-height:1.8;max-width:520px}.form-side{display:grid;place-items:center;padding:30px}.box{width:min(390px,100%)}h2{font-size:29px;margin:0 0 8px}.muted{color:#7e879d;margin-bottom:30px}label{font-weight:700;display:block;margin:17px 0 8px}input{width:100%;padding:13px;border:1px solid #dfe3ec;border-radius:10px;font-size:14px}button{width:100%;padding:13px;margin-top:23px;border:0;border-radius:10px;background:#6956e8;color:#fff;font-weight:700}.error{color:#c63f51;margin-top:7px}.demo{margin-top:25px;padding:14px;background:#efedff;border-radius:10px;color:#5c4bc0;font-size:12px;line-height:1.7}@media(max-width:760px){.page{grid-template-columns:1fr}.hero{display:none}}</style></head><body><main class="page"><section class="hero"><div class="brand">◆ EDVORA ERP</div><h1>One school.<br>Every operation, connected.</h1><p>A secure, local-first command centre for academics, attendance, finance, staff and parent communication.</p></section><section class="form-side"><form class="box" method="post" action="{{route('login')}}">@csrf<h2>Welcome back</h2><div class="muted">Sign in to your school workspace</div><label>Email address</label><input type="email" name="email" value="{{old('email')}}" required autofocus>@error('email')<div class="error">{{$message}}